import { Schema as S } from "effect";
import type { Command } from "foldkit";
import { Submodel } from "foldkit";
import type { Html } from "foldkit/html";
import { html } from "foldkit/html";

import * as Checkbox from "../../ui/shadcn-checkbox";

// MODEL

export const Model = S.Struct({});
export type Model = typeof Model.Type;

// MESSAGE

export const Message = S.Never;
export type Message = typeof Message.Type;

// INIT

export const init = (): readonly [
  Model,
  readonly Command.Command<Message>[],
] => [{}, []];

// UPDATE

export const update = (
  model: Model,
  _message: Message
): readonly [Model, readonly Command.Command<Message>[]] => [model, []];

// VIEW

export const view = Submodel.defineView<Model, Message>((): Html => {
  const h = html<Message>();

  return h.div(
    [h.Class("mx-auto w-56")],
    [
      h.div(
        [
          h.DataAttribute("invalid", ""),
          h.Class(Checkbox.shadcnCheckboxRowClasses),
        ],
        [
          h.button(
            [
              h.Type("button"),
              h.Id("terms-checkbox-invalid"),
              h.Name("terms-checkbox-invalid"),
              h.Role("checkbox"),
              h.AriaChecked(false),
              h.AriaInvalid(true),
              h.Class(Checkbox.shadcnCheckboxControlClasses),
            ],
            []
          ),
          h.label(
            [
              h.For("terms-checkbox-invalid"),
              h.Class(Checkbox.shadcnCheckboxLabelClasses),
            ],
            ["Accept terms and conditions"]
          ),
        ]
      ),
    ]
  );
});

import { Scene } from "foldkit";
import { describe, test } from "vitest";

import * as Example from "./main";

describe("Shadcn Checkbox Invalid example", () => {
  test("renders the origin invalid checkbox demo", () => {
    Scene.scene(
      { update: Example.update, view: Example.view },
      Scene.with(Example.init()[0]),
      Scene.expect(
        Scene.role("checkbox", { name: "Accept terms and conditions" })
      ).toHaveAttr("aria-invalid", "true"),
      Scene.expect(
        Scene.role("checkbox", { name: "Accept terms and conditions" })
      ).not.toHaveHandler("click")
    );
  });
});
